SELECT COUNT(*) FROM gw_leave_req
 WHERE user_id = #{userId}
   AND status_cd IN ('IN_PROGRESS','APPROVED')
   AND deleted_at IS NULL
   AND start_dt <= #{end} AND end_dt >= #{start}

mapper.update:
UPDATE gw_leave_balance
   SET annual_used = annual_used + #{days}, updated_at = CURRENT_TIMESTAMP
 WHERE user_id = #{userId} AND bal_year = #{year}
